/* Orbit 0.3: incremental integrations; rewards remain exclusively server-owned. */
function levelProgress(total){
 const xp=Math.max(0,Number(total)||0),level=Math.min(100,Math.max(0,Math.floor((-15+Math.sqrt(225+20*xp))/10)));
 const floor=5*level*level+15*level,next=level===100?floor:5*(level+1)**2+15*(level+1);
 return {level,current:level===100?0:xp-floor,required:next-floor,percent:level===100?100:Math.min(100,(xp-floor)/(next-floor)*100)};
}
const canonicalRedirect='https://pkuai.github.io/enemizadesorbit/';
const preferenceDefaults={interface:'orbit',animation:'expanded',fontSize:'medium',hidePhotos:false,hideRankingChanges:false,sound:'off',soundPack:'orbit',notification:'all',sessionAverage:true,personalGoal:45,taskPriority:'Média',deadlineNotice:true,theme:state.theme,density:state.density,bold:state.bold,reduced:state.reduced};
let accountPreferences={...preferenceDefaults},preferencesOwner=null,settingsTab='preferences';
const applyOriginalPrefs=applyPrefs;
applyPrefs=function(){applyOriginalPrefs();document.body.dataset.interface=accountPreferences.interface;document.body.dataset.animation=accountPreferences.animation;document.body.dataset.fontSize=accountPreferences.fontSize;document.body.classList.toggle('hide-photos',accountPreferences.hidePhotos);if(accountPreferences.animation==='reduced')document.body.classList.add('reduced');};
const reducedOriginal=reducedMotion;
reducedMotion=function(){return accountPreferences.animation==='reduced'||reducedOriginal();};
const pageAnimationOriginal=playPageAnimation;
playPageAnimation=function(el,frames,opts){return pageAnimationOriginal(el,frames,{...opts,duration:opts.duration*(accountPreferences.animation==='medium'?.8:1)});};
async function readPreferences(){const data=await orbitApi('preferences_get');preferencesOwner=live.user.id;accountPreferences={...preferenceDefaults,...data};for(const k of ['theme','density','bold','reduced'])if(k in accountPreferences)state[k]=accountPreferences[k];applyPrefs();}
let preferenceQueue=Promise.resolve();
function setOnlinePreference(key,value){
 accountPreferences[key]=value;if(['theme','density','bold','reduced'].includes(key))state[key]=value;save();applyPrefs();render();
 const owner=live.user?.id;
 preferenceQueue=preferenceQueue.catch(()=>{}).then(async()=>{if(!live.member||live.user.id!==owner)return;await orbitApi('preferences_patch',{[key]:value});}).catch(e=>toast('Preferência aplicada neste aparelho; falha ao sincronizar: '+e.message));
 return preferenceQueue;
}
setTheme=t=>setOnlinePreference('theme',t);setDensity=t=>setOnlinePreference('density',t);toggleBold=()=>setOnlinePreference('bold',!state.bold);
function settingChoice(key,label,options){return `<label class="field">${esc(label)}<select onchange="setOnlinePreference('${key}',this.value)">${options.map(([v,n])=>`<option value="${v}" ${String(accountPreferences[key])===String(v)?'selected':''}>${esc(n)}</option>`).join('')}</select></label>`;}
