 settingsGroup('Sons e notificações',settingChoice('sound','Feedback sonoro',[['off','Desligado'],['local','Visual + som local']])+settingChoice('soundPack','Amostra sonora provisória',[['orbit','Orbit'],['pulse','Pulse'],['aura','Aura'],['aero','Aero']])+actionButton('Ouvir amostra','playFeedback')+settingChoice('notification','Notificações no aplicativo',[['personal','Pessoais'],['general','Gerais'],['all','Todas'],['off','Desligadas']])+'<p class="muted small">As amostras usam tons sintetizados provisórios. Os pacotes sonoros oficiais e o push em segundo plano ainda não estão integrados.</p>');
