function updateOrbesBalance(){const el=$('#orbesCounter');if(!el)return;const value=features.overview?.stats.orbes;el.innerHTML=identityIcon('orbes')+'<span>'+ (Number.isFinite(value)?fmt(value):'—')+'</span><span class="orbes-name">Orbes</span>';el.title=Number.isFinite(value)?'Seu saldo de Orbes':'Regras de concessão de Orbes ainda não confirmadas';el.setAttribute('aria-label',el.title);}
