// Installs the approved reference popup without inheriting its illustrative rewards.
let rewardOverlay=null,rewardReceipt=null,rewardReturn=null;
function receiptData(events,options={}){
 const sum=k=>events.reduce((n,e)=>n+Number(e[k]||0),0),known=events.every(e=>e.reward_meta),meta=events.map(e=>e.reward_meta).filter(Boolean),single=events.length===1?events[0].reward_meta:null;
 let rows=single?[['Pontuação-base',fmt(single.base_pr)+' PR'],['Freio de aproveitamento','× '+fmt(single.brake)],['Multiplicador de patente','× '+fmt(single.rank_multiplier)],['Bônus',fmt(single.bonus||0)+' PR'],['Penalidade',fmt(single.penalty||0)+' PR'],['PR final',fmt(sum('pr'))+' PR']]:events.map(e=>[(e.kind==='bank'?'Banco de Questões':e.kind==='external'?'Questões Externas':e.kind==='match'?'Coliseu':e.kind)+' · '+dateLabel(e.created_at),fmt(e.pr)+' PR']);
 if(single?.competitive){rows=[['Pontuação-base própria',fmt(single.base_pr)+' PR'],['Freio de aproveitamento','× '+fmt(single.brake)],['Multiplicador de patente','× '+fmt(single.rank_multiplier)],['Regra',single.rule||'Confrontos virtuais'],...(single.virtual||[]).map(v=>[person(v.rival)+' · '+(v.result==='win'?'vitória':'derrota'),fmt(v.pr)+' PR']),['Resultado final',fmt(sum('pr'))+' PR']];}if(!single)rows.push(['PR total',fmt(sum('pr'))+' PR']);
 return {mode:'session',title:'ATIVIDADE CONCLUÍDA',type:'ATIVIDADE · RECIBO',summary:sum('correct')+' acertos · '+sum('wrong')+' erros',values:[sum('pr'),sum('xp'),known?meta.reduce((n,m)=>n+Number(m.synapse||0),0):null,meta.length===events.length&&meta.every(m=>m.orbes!=null)?meta.reduce((n,m)=>n+Number(m.orbes||0),0):null],calcs:rows,note:known?'Recibo de ganhos já registrados. A Sinapse mostra o acréscimo na atividade; seu valor atual também considera o tempo decorrido.':'Registro histórico preservado. O detalhamento original de Sinapse, Orbes e multiplicadores não foi armazenado nesta versão antiga.',...options,light:['light','rose','cream','hzn-light'].includes(state.theme),reduced:reducedMotion()};
}
function showRewardPopup(events,options={}){if(!events?.length)return;rewardReturn=document.activeElement;rewardReceipt=receiptData(events,options);if(rewardOverlay)rewardOverlay.remove();rewardOverlay=document.createElement('div');rewardOverlay.className='reward-overlay';rewardOverlay.setAttribute('role','dialog');rewardOverlay.setAttribute('aria-modal','true');rewardOverlay.setAttribute('aria-label','Recompensas da atividade');const frame=document.createElement('iframe');frame.src='assets/reward-frame.html?v=0.3.0';frame.title='Recompensas registradas';frame.onload=()=>{frame.contentWindow.postMessage({type:'orbit-receipt',receipt:rewardReceipt},location.origin);frame.contentWindow.focus();};rewardOverlay.append(frame);document.body.append(rewardOverlay);document.body.classList.add('reward-open');}
function closeRewardPopup(){rewardOverlay?.remove();rewardOverlay=null;rewardReceipt=null;document.body.classList.remove('reward-open');if(rewardReturn?.isConnected)rewardReturn.focus();}
window.addEventListener('message',e=>{if(!rewardOverlay||e.origin!==location.origin||e.source!==rewardOverlay.querySelector('iframe').contentWindow)return;if(e.data?.type==='orbit-receipt-close')closeRewardPopup();if(e.data?.type==='orbit-receipt-ready'&&rewardReceipt)e.source.postMessage({type:'orbit-receipt',receipt:rewardReceipt},location.origin);});
async function openRewardReceipt(id){try{const event=await orbitApi('reward_receipt',{id});if(!event){toast('Recibo indisponível para esta conta.');return;}showRewardPopup([event]);}catch(e){toast('Falha ao carregar recibo: '+e.message);}}
const sessionJoinRevision=joinSession;
joinSession=async function(room){const current=live.sessions.find(s=>s.user_id===live.user.id),leaving=current?.room===room;await sessionJoinRevision(room);if(leaving&&!live.sessions.some(s=>s.user_id===live.user.id)){try{const events=await checked(db.from('orbit_events').select('*').eq('user_id',live.user.id).gte('created_at',current.started_at).order('created_at'));if(events.some(e=>e.correct+e.wrong>0))showRewardPopup(events,{title:'SESSÃO CONCLUÍDA',type:'SESSÃO · '+room});}catch(e){toast('Sessão encerrada. Recibos disponíveis no histórico.');}}};
const addExternalRevision=addExternal;
addExternal=function(){const request_id=crypto.randomUUID();let proofPath=null;formModal('Registrar questões','A recompensa será concedida uma única vez após validação administrativa.',field('source','Fonte / atividade','','text','required maxlength="200"')+field('correct','Acertos',0,'number','required min="0" max="10000"')+field('wrong','Erros',0,'number','required min="0" max="10000"')+'<label class="field">Comprovante<input name="proof" type="file" accept="image/png,image/jpeg,image/webp,application/pdf" required></label>',async(p,f)=>{const file=f.elements.proof.files[0];if(file.size>5242880)throw Error('O arquivo deve ter até 5 MB.');if(!proofPath){proofPath=live.user.id+'/proof/'+request_id;await checked(db.storage.from('orbit-uploads').upload(proofPath,file,{contentType:file.type,upsert:false}));}await orbitApi('external_add',{request_id,source:p.source,correct:+p.correct,wrong:+p.wrong,proof_path:proofPath});setTimeout(()=>showRewardPopup([{kind:'external',correct:+p.correct,wrong:+p.wrong,xp:0,pr:0,reward_meta:{base_pr:0,brake:1,rank_multiplier:1,bonus:0,penalty:0,synapse:0,orbes:null},created_at:new Date().toISOString()}],{title:'REGISTRO ENVIADO',type:'QUESTÕES EXTERNAS',subtitle:'Aguardando validação. Nenhuma recompensa concedida ainda.',note:'O registro pendente não altera PR, XP ou Sinapse. Após aprovação, o recibo real ficará disponível no histórico.'}),0);});};
