const isCompetition=r=>r?.mode&&r.mode!=='legacy';
async function competitionApi(action,p={}){return checked(db.rpc('orbit_competition',{action,p}));}
async function refreshCompetition(action='state',p={}){const id=features.run?.id;if(!id)return;const data=await competitionApi(action,{id,...p});if(features.run?.id!==id)return;const oldMine=features.players.find(pl=>pl.run_id===id&&pl.user_id===live.user.id);features.run=data.run;features.lobby=data.lobby||[];features.players=features.players.filter(pl=>pl.run_id!==id||pl.user_id!==live.user.id);features.players.push(data.mine);features.runIndex=Math.max(0,data.mine.question_index-1);features.competitionState=data;
 if(oldMine?.status==='playing'&&['finished','wo'].includes(data.mine.status)){await loadFeatures();await refreshSessions();const events=features.events.filter(e=>e.ref==='contest-xp:'+id||e.ref==='contest-pr:'+id);const settled=data.run.settlement==='settled',positive=Number(data.mine.pr_result)>=0;showRewardPopup(events,{title:settled?(positive?'VITÓRIA':'DERROTA'):'PARTICIPAÇÃO CONCLUÍDA',mode:settled?(positive?'win':'lose'):'session',type:'COLISEU · '+(data.run.mode==='daily'?'DUELO DIÁRIO':'COMET'),subtitle:settled?'Resultado competitivo registrado.':'XP registrado. Aguarde o resultado dos demais participantes.'});}
}
createRun=function(kind){if(kind!=='match')return legacyCreateRun(kind);const rivals=live.profiles.filter(p=>p.user_id!==live.user.id);formModal('Nova participação no Coliseu','Duelos assíncronos. O piloto atual aceita confrontos entre jogadores da mesma patente.',field('title','Nome da partida','','text','required maxlength="100"')+selectField('mode','Modalidade',[['comet-b','Comet B · 6 ENEM · 90s por questão'],['comet-a','Comet A · 8 curtas revisadas · 60s'],['daily','Duelo Diário · 24 ENEM · 90s']],'comet-b')+`<fieldset><legend>Convidar enemizades</legend>${rivals.map(p=>`<label class="row"><input name="rival" type="checkbox" value="${p.user_id}"> ${esc(p.display_name)}</label>`).join('')||empty('Convide outros testadores para criar uma partida.')}</fieldset><p class="small muted">Comet A exige questões marcadas como curtas após revisão editorial. Regras de bônus contra patente superior ainda precisam ser confirmadas.</p>`,async(p,f)=>{const players=[...f.querySelectorAll('[name=rival]:checked')].map(el=>el.value);const result=await competitionApi('create',{mode:p.mode,title:p.title,players});await loadFeatures();features.run=features.runs.find(r=>r.id===result.id);features.runIndex=0;features.results=null;await refreshCompetition();});};
const previousFeatureRuns=featureRuns;
views.coliseum=()=>{if(features.run?.kind==='match')return runScreen();const list=features.runs.filter(r=>r.kind==='match'&&features.players.some(p=>p.run_id===r.id&&p.user_id===live.user.id));return head('Coliseu','Duelos Diários e Comet · início individual após todos aceitarem.',actionButton('Criar partida','createRun',['match'],'primary'))+`<div class="grid2">${['daily','comet'].map(group=>`<section class="card"><h2>${group==='daily'?'Duelos Diários':'Partidas Comet'}</h2><p class="muted mt">${group==='daily'?'24 questões · 90s cada · 36h para aceitar · 1 enviado e 2 recebidos por dia.':'A: 8 curtas / 60s · B: 6 ENEM / 90s · início individual em até 48h após os aceites.'}</p>${list.filter(r=>group==='daily'?r.mode==='daily':r.mode!=='daily').map(r=>`<div class="listline"><div><b>${esc(r.title)}</b><p>${r.mode==='legacy'?'Partida anterior':r.mode} · ${runLabel(r.status)}</p></div>${actionButton('Abrir','openRun',[r.id])}</div>`).join('')||empty('Nenhuma partida nesta modalidade.')}</section>`).join('')}</div><p class="notice mt">Confrontos entre patentes diferentes aguardam a confirmação das fórmulas. Empates exatos e W.O. em Diários ficam com PR pendente para evitar conceder valores sem regra aprovada. Orbes permanecem sem concessão.</p>`;};
runScreen=function(){if(!isCompetition(features.run))return legacyRunScreen();const r=features.run,mine=features.players.find(p=>p.run_id===r.id&&p.user_id===live.user.id),lobby=features.lobby||[];let html=head(esc(r.title),(r.mode==='daily'?'Duelo Diário':r.mode==='comet-a'?'Comet A':'Comet B')+' · '+runLabel(r.status),actionButton('Voltar à lista','closeRun'));
 if(r.status==='waiting')return html+`<section class="card"><h2>Aguardando aceites</h2>${lobby.map(p=>`<div class="listline"><b>${esc(person(p.user_id))}</b><span>${esc(({invited:'Convidado',accepted:'Confirmado',declined:'Recusou'})[p.status]||p.status)}</span></div>`).join('')}${r.invite_expires_at?`<p class="muted mt">Aceitar até ${dateLabel(r.invite_expires_at)}</p>`:''}<div class="row mt">${mine?.status==='invited'?actionButton('Aceitar','competitionAction',['accept'],'primary')+actionButton('Recusar','competitionAction',['decline']):'<p class="muted">A janela de 48h começa quando todos aceitarem.</p>'}</div></section>`;
 if(r.status==='cancelled')return html+empty('Partida cancelada ou convite expirado.');
 if(r.status==='finished')return html+`<section class="card"><h2>Resultado</h2>${lobby.slice().sort((a,b)=>(b.correct||0)-(a.correct||0)||(a.elapsed||0)-(b.elapsed||0)).map(p=>`<div class="listline"><b>${esc(person(p.user_id))}</b><span>${p.status==='wo'?'W.O.':p.correct+' acertos · '+p.elapsed+'s'} · ${p.pr_result==null?'PR pendente':fmt(p.pr_result)+' PR'}</span></div>`).join('')}<p class="muted mt">${r.settlement==='rules_pending'?'XP registrado. PR aguarda confirmação das regras de empate exato ou W.O. do Duelo Diário.':'Recompensas registradas uma única vez.'}</p>${actionButton('Ver meus recibos','competitionReceipts',[r.id],'mt')}${actionButton('Ver correção','showCompetitionCorrection',[r.id],'mt')}</section>`;
 if(mine?.status==='accepted')return html+`<section class="card"><h2>Seu início é individual</h2><p class="mt">Inicie até ${dateLabel(r.ends_at)}. Após começar, o tempo continua mesmo com o site fechado. Cada questão tem até ${r.question_seconds} segundos.</p>${actionButton('Iniciar minha participação','competitionAction',['begin'],'primary mt')}</section>`;
 if(['finished','wo'].includes(mine?.status))return html+`<section class="card"><h2>Sua participação terminou</h2><p class="mt">Aguarde os demais até ${dateLabel(r.ends_at)}.</p>${actionButton('Atualizar resultado','competitionAction',['state'],'mt')}${actionButton('Ver meu recibo','competitionReceipts',[r.id],'mt')}</section>`;
 const q=live.questions.find(q=>q.id===r.question_ids[(mine?.question_index||1)-1]);if(!q)return html+empty('Atualizando a participação…');return html+`<section class="card"><div class="between"><b>Questão ${mine.question_index} / ${r.question_ids.length}</b><time id="competitionClock"></time></div><div class="question mt">${richText(q.context)}<p class="mt">${richText(q.prompt)}</p></div><div class="options">${q.alternatives.map(a=>`<button class="option" ${features.busy?'disabled':''} onclick="${call('competitionAnswer',q.id,a.letter)}"><b>${a.letter}</b><span>${richText(a.text)}${safeImage(a.file)?`<img src="${esc(a.file)}" alt="Alternativa ${a.letter}">`:''}</span></button>`).join('')}</div><p class="small muted mt">Ao escolher, sua resposta é confirmada e a próxima questão começa. O prazo é verificado no servidor.</p>${actionButton('Encerrar minha participação','confirmCompetitionFinish',[],'mt')}</section>`;};
