/* Video playback and reading state reuse the existing private progress records. */
let activeReadingSave=null;const closeBeforeReading=closeModal;closeModal=function(){const flush=activeReadingSave;activeReadingSave=null;if(flush)flush();closeBeforeReading();};
const materialReaderRevision=openMaterial;
openMaterial=async function(id){if(activeReadingSave){const flush=activeReadingSave;activeReadingSave=null;await flush();}await materialReaderRevision(id);const m=features.materials.find(m=>m.id===id),form=$('#materialProgress'),video=$('#materialVideo');if(!m||!form)return;const previous=myDocuments('progress').find(d=>d.data.material===id);let docId=previous?.id||crypto.randomUUID(),busySave=false,pending=false;
 async function saveReading(){if(busySave){pending=true;return;}busySave=true;try{await orbitApi('document_save',{id:docId,kind:'progress',title:m.title,data:{material:id,position:Number(form.elements.position.value),notes:form.elements.notes.value,highlight:form.elements.highlight.value,done:form.elements.done.checked,playbackRate:video?.playbackRate||1,last_opened:new Date().toISOString()}});const local=features.documents.find(d=>d.id===docId);const data={material:id,position:Number(form.elements.position.value),notes:form.elements.notes.value,highlight:form.elements.highlight.value,done:form.elements.done.checked,playbackRate:video?.playbackRate||1,last_opened:new Date().toISOString()};if(local)local.data=data;else features.documents.push({id:docId,kind:'progress',title:m.title,data});}catch(e){toast('Não foi possível salvar a posição: '+e.message);}finally{busySave=false;if(pending){pending=false;saveReading();}}}
 activeReadingSave=saveReading;form.onsubmit=async e=>{e.preventDefault();await saveReading();toast('Progresso salvo.');};
 if(video){const speed=document.createElement('label');speed.className='field mt';speed.textContent='Velocidade de reprodução';const select=document.createElement('select');for(const value of [.5,.75,1,1.25,1.5,1.75,2]){const o=new Option(value+'×',value);o.selected=value===(previous?.data.playbackRate||1);select.append(o);}select.onchange=()=>{video.playbackRate=+select.value;saveReading();};speed.append(select);video.after(speed);video.playbackRate=previous?.data.playbackRate||1;let lastSave=0;video.addEventListener('timeupdate',()=>{if(Date.now()-lastSave>=10000){lastSave=Date.now();saveReading();}});video.addEventListener('pause',saveReading);video.addEventListener('ended',saveReading);}
 const related=features.materials.filter(other=>other.id!==id&&((m.related_ids||[]).includes(other.id)||other.subject===m.subject)).slice(0,4);if(related.length){const box=document.createElement('section');box.className='mt';box.innerHTML='<h3>Materiais relacionados</h3><div class="row wrap mt">'+related.map(other=>actionButton(other.title,'openMaterial',[other.id])).join('')+'</div>';form.after(box);}
};
const libraryViewRevision=views.library;
views.library=()=>{const recent=myDocuments('progress').sort((a,b)=>String(b.updated_at||'').localeCompare(String(a.updated_at||''))).slice(0,4).filter(d=>features.materials.some(m=>m.id===d.data.material));return (recent.length?`<section class="card mb"><h2>Retomar leitura</h2><div class="row wrap mt">${recent.map(d=>actionButton(d.title,'openMaterial',[d.data.material])).join('')}</div></section>`:'')+libraryViewRevision();};
// Active notifications are displayed outside the header, leaving session indicators clear.
const silentToast=toast;
toast=function(message){silentToast(message);if(accountPreferences.sound==='local')playFeedback();};

/* Meu Norte uses the real schedule; generation remains disabled until approved. */
titles.ai='Meu Norte';document.querySelector('[data-go="ai"] span')?.replaceChildren(document.createTextNode('Meu Norte'));
views.ai=()=>{const tasks=myDocuments('task'),done=tasks.filter(d=>d.data.done).length,overdue=tasks.filter(d=>!d.data.done&&d.data.date&&d.data.date<localDay());return head('Meu Norte','Seu cronograma, suas metas e seu progresso.')+`<div class="grid2"><section class="card"><h2>Seu objetivo</h2><p class="mt">${esc(live.user.user_metadata?.study_goal||'Avançar um pouco a cada dia.')}</p><div class="grid2 mt">${stat('Tarefas concluídas',done,'De '+tasks.length,'check')}${stat('Pendências',overdue.length,'Sem horários obrigatórios','calendar')}</div>${overdue.length&&accountPreferences.deadlineNotice?'<p class="notice mt">Há tarefas atrasadas. Você decide se deseja reagendá-las.</p>':''}<div class="row wrap mt">${actionButton('Nova tarefa','editTask',[],'primary')}${overdue.length?actionButton('Revisar reagendamento','proposeReschedule'):''}</div></section><section class="card"><h2>Conversa com Meu Norte</h2><p class="muted mt">A geração de conteúdo com IA está em validação. Seu cronograma e os materiais existentes continuam disponíveis.</p><div class="row wrap mt">${actionButton('Abrir biblioteca','go',['library'])}${actionButton('Praticar questões','go',['bank'])}</div></section><section class="card" style="grid-column:1/-1"><h2>Cronograma flexível</h2><div class="mt">${taskRows()}</div></section></div>`;};
function proposeReschedule(){const tasks=myDocuments('task').filter(d=>!d.data.done&&d.data.date&&d.data.date<localDay()),date=new Date(localDay()+'T12:00:00Z');date.setUTCDate(date.getUTCDate()+1);const target=date.toISOString().slice(0,10);modal('Revisar reagendamento','Nenhuma data muda antes da sua aprovação.',`<p>Proposta: mover estas pendências para ${esc(target)}.</p>${tasks.map(d=>`<div class="listline"><b>${esc(d.title)}</b><span>${esc(d.data.date)} → ${target}</span></div>`).join('')}<div class="row mt">${actionButton('Aprovar reagendamento','approveReschedule',[tasks.map(d=>d.id),target],'primary')}${actionButton('Manter datas atuais','closeModal')}</div>`);}
async function approveReschedule(ids,date){await guarded(async()=>{for(const id of ids){const d=byId(id);if(!d||d.data.done)continue;await orbitApi('document_save',{id,kind:'task',title:d.title,data:{...d.data,date}});}await loadFeatures();closeModal();render();toast('Datas atualizadas com sua aprovação.');});}
let rankChanges=new Map(),previousRanks=null;
function trackRanking(overview){const ranks=[...overview.ranks].sort((a,b)=>b.stats.pr-a.stats.pr||b.stats.xp-a.stats.xp||a.profile.user_id.localeCompare(b.profile.user_id));const next=new Map(ranks.map((r,i)=>[r.profile.user_id,i+1]));if(previousRanks){for(const [id,pos] of next){const old=previousRanks.get(id);if(old&&old!==pos)rankChanges.set(id,old-pos);}}previousRanks=next;}
const previousRankingRow=rankingRow;
rankingRow=function(r,i){const html=previousRankingRow(r,i),delta=rankChanges.get(r.profile.user_id)||0,label=delta>0?'↑ '+delta:delta<0?'↓ '+Math.abs(delta):'—';return accountPreferences.hideRankingChanges?html:html.replace('</span><button class="ranking-person"',`<small class="rank-change ${delta>0?'up':delta<0?'down':''}" aria-label="${delta?'Variação de '+delta+' posições':'Sem variação observada nesta sessão'}">${label}</small></span><button class="ranking-person"`);};
const previousAccountTracking=updateAccount;
updateAccount=function(){if(features.overview)trackRanking(features.overview);previousAccountTracking();};

function cropValue(p){return Math.max(0,Math.min(100,Number(p?.avatar_position)??50));}
const avatarCropOriginal=avatar,rankingCropOriginal=rankingAvatar;
avatar=function(id){const p=live.profiles.find(p=>p.user_id===id);return avatarCropOriginal(id).replace('<img ','<img style="object-position:50% '+(Number.isFinite(cropValue(p))?cropValue(p):50)+'%" ');};
rankingAvatar=function(profile){return rankingCropOriginal(profile).replace('<img ','<img style="object-position:50% '+(Number.isFinite(cropValue(profile))?cropValue(profile):50)+'%" ');};
const profileCropView=views.profile;
views.profile=()=>profileCropView().replace('<form id="profileForm"',actionButton('Ajustar enquadramento da foto','editAvatarFraming',[],'mb')+'<form id="profileForm"');
function editAvatarFraming(){const image=features.avatarUrls[live.user.id];if(!image){toast('Envie sua foto de perfil primeiro.');return;}formModal('Enquadramento da foto','Arraste para ajustar o recorte vertical em todos os dispositivos.',`<img id="avatarFramePreview" src="${esc(image)}" alt="Prévia do enquadramento" style="display:block;width:150px;height:150px;border-radius:35px;object-fit:cover;object-position:50% ${live.profile.avatar_position??50}%"><label class="field">Posição vertical<input name="position" type="range" min="0" max="100" value="${live.profile.avatar_position??50}" oninput="document.getElementById('avatarFramePreview').style.objectPosition='50% '+this.value+'%'"></label>`,async p=>{const avatar_position=Math.max(0,Math.min(100,Math.round(+p.position)));await checked(db.from('orbit_profiles').update({avatar_position}).eq('user_id',live.user.id));live.profile.avatar_position=avatar_position;await refreshSessions();updateAccount();});}
const accountCropUpdate=updateAccount;
updateAccount=function(){accountCropUpdate();$('.sidefoot .version').textContent='Orbit · testes online 0.3';document.querySelectorAll('.account .avatar img,.topbar .avatar img').forEach(e=>e.style.objectPosition='50% '+(live.profile.avatar_position??50)+'%');};
gate('Carregando acesso…');startOnline();
